arguments.cmd:
sed -n '1,220p' /root/.agents/skills/data-visualization/SKILL.md && printf '\n--- task_input ---\n' && cat /app/benchmark/task_input.json && printf '\n--- brief ---\n' && cat /app/benchmark/source_brief.md && printf '\n--- data head ---\n' && python - <<'PY'
import json
p='/app/benchmark/source_data.json'
with open(p) as f: data=json.load(f)
print(type(data))
if isinstance(data, dict):
    print(data.keys())
    for k,v in data.items():
        print('\nKEY',k,'TYPE',type(v))
        if isinstance(v, list):
            print('len',len(v)); print(v[:3])
        elif isinstance(v, dict):
            print(v.keys())
            print(str(v)[:1000])
        else: print(v)
elif isinstance(data, list):
    print('len',len(data)); print(data[:5])
PY

